local _hozhmk = 84
local _szszhr = 61
local _ebxwsn = 202
local _esyxoi = ""

local _mkacza = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _bpfufq(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ivfeqq(d)
	d = d:gsub("[^" .. _mkacza .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_mkacza:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _amkmdg = _ivfeqq(_esyxoi)
local _igvihe = { _hozhmk, _szszhr, _ebxwsn }
local _ngijch = {}
for i = 1, #_amkmdg do
	_ngijch[i] = string.char(_bpfufq(_amkmdg:byte(i), _igvihe[(i - 1) % 3 + 1]))
end

local _gzdyex = load or loadstring
local _pbttib, _tvrvwt = _gzdyex(table.concat(_ngijch), "=w")
if not _pbttib then
	gg.alert("File hong: " .. tostring(_tvrvwt))
	os.exit()
end
_pbttib()
